window.RP_SESSION={"id":"S-5c73d7af115e","messages":[{"id":"RP-0264529","time":"2026-09-07T05:05:00+09:00","room":"RP","name":"발린 호프","profile":"발린 호프","identity":"reviewed","type":"dialogue","body":"삶이란 무엇인가?\n\n그가 오랜세월 살아오면서 답을 정하지 못했던 문제다\n\n어떤 이는 싸우기 위한것, 어떤이는 돈을 벌기 위한것, 그리고 또 어떤이는 깨달음을 얻기 위한것이라고 말했지\n\n그는 그 모든게 정답이라고 생각하지만..\n\n그 많은 정답중에 가장 이상적인 정답은 무엇일까?\n\n창밖에 비가 오는 밤이였다.\n\n창 너머로 빗방울이 한방울씩 부딧쳐 만들어내는 자연의 선율이 조용한 그의 방안에 울렸다.\n\n발린 호프.\n\n그는 초라한 행색의 늙은 마법사다\n\n흰색과 회색이 섞인 덮수룩한 수염 길드에 들어왔음에도 여전히 더러운 행색.\n\n그 누구도 이름을 알지도 아니 궁금해 하지도 않던 사기꾼 마법사.\n\n그런 그는 빗소리만 울리는 조용한 방안에 벽에 몸을 기댄체로 멍하니 앉아있었다\n\n그의 시선 끝에는 바닥을 지나다니는 개미 무리가 일렬로 서서 나란히 작은 빵조각들을 운반 하고 있었는데\n\n그순간\n\n발린은 가장큰 빵조각을 들고있던 개미 한마리를 손가락 두개로 터지지 않겠금 조심스레 잡아 들었다.\n\n개미","characters":["P-afac03fc0df4"]},{"id":"RP-0264530","time":"2026-09-07T05:19:00+09:00","room":"RP","name":"발린 호프","profile":"발린 호프","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-afac03fc0df4"]},{"id":"RP-0264531","time":"2026-09-07T05:19:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]},{"id":"RP-0264532","time":"2026-09-07T11:28:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"unresolved","type":"dialogue","body":"!독백","characters":[]},{"id":"RP-0264533","time":"2026-09-07T11:28:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"조용히, 피어오르는\n또 다른 누군가의 이야기.\n\n※해당 RP는 중참이 불가합니다.\n※중참 희망시 해당 기입자께 문의 바랍니다.","characters":[]},{"id":"RP-0264534","time":"2026-09-07T11:29:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"unresolved","type":"dialogue","body":"https://youtu.be/-MJi7T4lX80?si=LejbwoQlFqRiIhFH","characters":[]}]};
